{
  "model": "openai/gpt-4o-mini",
  "input": "Use the deepwiki tool to ask what the facebook/react repo is about, one sentence.",
  "tools": [
    {
      "type": "mcp",
      "server_label": "deepwiki",
      "server_url": "https://mcp.deepwiki.com/mcp",
      "require_approval": "never",
      "allowed_tools": [
        "ask_question"
      ]
    }
  ],
  "max_output_tokens": 256
}

{
  "model": "openai/gpt-4o-mini",
  "input": [
    {
      "role": "user",
      "content": [
        {
          "type": "input_text",
          "text": "Two attachments follow. In one sentence: name the colour of the image, then say what the document is."
        },
        {
          "type": "input_image",
          "image_url": "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAACAAAAAgCAIAAAD8GO2jAAAAJ0lEQVR42u3NsQkAAAjAsP7/tF7hIASyp6lTCQQCgUAgEAgEgi/BAjLD/C5w/SM9AAAAAElFTkSuQmCC"
        },
        {
          "type": "input_file",
          "file_url": "https://www.berkshirehathaway.com/letters/2024ltr.pdf"
        }
      ]
    }
  ],
  "max_output_tokens": 256
}

{
  "model": "openai/gpt-5-mini",
  "input": "Use the code_exec tool to run: print(\"hello\")",
  "tools": [
    {
      "type": "custom",
      "name": "code_exec",
      "description": "Executes arbitrary python code",
      "format": {
        "type": "text"
      }
    }
  ],
  "tool_choice": {
    "type": "custom",
    "name": "code_exec"
  },
  "max_output_tokens": 2048
}

{
  "contents": [
    {
      "role": "user",
      "parts": [
        {
          "text": "Count in lowercase words: one, two, three, four, five"
        }
      ]
    }
  ],
  "generationConfig": {
    "stopSequences": [
      "three"
    ],
    "maxOutputTokens": 64,
    "thinkingConfig": {
      "thinkingBudget": 0
    }
  }
}

{
  "contents": [
    {
      "role": "user",
      "parts": [
        {
          "text": "Compute the 50th Fibonacci number with code and state it."
        }
      ]
    }
  ],
  "tools": [
    {
      "codeExecution": {}
    }
  ],
  "generationConfig": {
    "maxOutputTokens": 1024
  }
}

{
  "contents": [
    {
      "role": "user",
      "parts": [
        {
          "text": "In one sentence, what is https://www.wikipedia.org/ about?"
        }
      ]
    }
